import React, { useState, useEffect, useRef } from 'react';
import gsap from 'gsap';
import { pinApi } from '../utils/api';

const LandingPage = () => {
  const [heroImages, setHeroImages] = useState([]);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const leftImagesRef = useRef([]);
  const rightImagesRef = useRef([]);
  const heroTextRef = useRef(null);
  const dotsRef = useRef(null);

  // Fetch images from admin uploads
  useEffect(() => {
    const fetchHeroImages = async () => {
      try {
        const pins = await pinApi.getPins();
        // Filter for hero-worthy images (you can adjust criteria)
        const heroPins = pins.filter(pin => 
          pin.image && 
          (pin.title?.length > 0 || pin.description?.length > 0)
        ).slice(0, 12); // Limit to 12 images for the hero section
        
        setHeroImages(heroPins);
      } catch (error) {
        console.error('Error fetching hero images:', error);
      }
    };

    fetchHeroImages();
  }, []);

  // Auto-rotate images every 4 seconds
  useEffect(() => {
    if (heroImages.length === 0) return;

    const interval = setInterval(() => {
      setCurrentImageIndex(prev => (prev + 1) % heroImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, [heroImages.length]);

  // Animate images when they change
  useEffect(() => {
    if (heroImages.length === 0) return;

    // Animate left images
    leftImagesRef.current.forEach((imgRef, index) => {
      if (imgRef) {
        gsap.to(imgRef, {
          opacity: index === currentImageIndex % 6 ? 1 : 0.7,
          scale: index === currentImageIndex % 6 ? 1.05 : 1,
          duration: 0.8,
          ease: "power2.out"
        });
      }
    });

    // Animate right images
    rightImagesRef.current.forEach((imgRef, index) => {
      if (imgRef) {
        gsap.to(imgRef, {
          opacity: index === currentImageIndex % 6 ? 1 : 0.7,
          scale: index === currentImageIndex % 6 ? 1.05 : 1,
          duration: 0.8,
          ease: "power2.out"
        });
      }
    });
  }, [currentImageIndex, heroImages.length]);

  // Initial page load animations
  useEffect(() => {
    // Hero text animation
    if (heroTextRef.current) {
      gsap.fromTo(heroTextRef.current,
        { opacity: 0, y: 30 },
        { opacity: 1, y: 0, duration: 1, ease: "power3.out" }
      );
    }

    // Slider dots animation
    if (dotsRef.current) {
      gsap.fromTo(dotsRef.current,
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 1, delay: 0.3, ease: "power3.out" }
      );
    }

    // Side images initial animation
    setTimeout(() => {
      [...leftImagesRef.current, ...rightImagesRef.current].forEach((imgRef, index) => {
        if (imgRef) {
          gsap.fromTo(imgRef,
            { opacity: 0, x: index % 2 === 0 ? -50 : 50, scale: 0.8 },
            { opacity: 0.7, x: 0, scale: 1, duration: 1, delay: index * 0.1, ease: "back.out(1.4)" }
          );
        }
      });
    }, 500);
  }, []);

  // Split images for left and right columns
  const leftImages = heroImages.filter((_, index) => index % 2 === 0).slice(0, 6);
  const rightImages = heroImages.filter((_, index) => index % 2 === 1).slice(0, 6);

  return (
    <div className="min-h-screen pt-20 pb-16 bg-white">
      {/* Hero Section */}
      <div className="container mx-auto px-4">
        <div className="flex flex-col lg:flex-row items-center justify-between gap-8 lg:gap-12">
          
          {/* Left Side Images */}
          <div className="hidden lg:block w-1/4">
            <div className="space-y-4">
              {leftImages.map((pin, index) => (
                <div 
                  key={pin.id} 
                  ref={el => leftImagesRef.current[index] = el}
                  className="relative group overflow-hidden rounded-2xl"
                  style={{ paddingBottom: `${Math.random() * 40 + 120}%` }}
                >
                  <img
                    src={pin.image_url}
                    alt={pin.title || 'Creative inspiration'}
                    className="absolute inset-0 w-full h-full object-cover transition-all duration-700"
                  />
                  {/* Gradient overlay at bottom */}
                  <div className="absolute inset-0 bg-gradient-to-t from-white via-white/30 to-transparent"></div>
                  
                  {/* Hover effect */}
                  <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                </div>
              ))}
            </div>
          </div>

          {/* Center Hero Content */}
          <div className="flex-1 flex flex-col items-center text-center max-w-2xl">
            <div ref={heroTextRef}>
              <h1 className="text-5xl md:text-6xl lg:text-7xl font-bold leading-tight mb-6">
                <span className="block text-gray-900">Get your next</span>
                <span className="block text-red-600">chai time snacks idea</span>
              </h1>
            </div>
            
            {/* Slider Dots */}
            <div ref={dotsRef} className="flex space-x-2 mt-8">
              {[...Array(3)].map((_, index) => (
                <div
                  key={index}
                  className={`w-3 h-3 rounded-full transition-all duration-300 ${
                    index === currentImageIndex % 3 
                      ? 'bg-red-600 scale-125' 
                      : 'bg-gray-300'
                  }`}
                ></div>
              ))}
            </div>
          </div>

          {/* Right Side Images */}
          <div className="hidden lg:block w-1/4">
            <div className="space-y-4">
              {rightImages.map((pin, index) => (
                <div 
                  key={pin.id} 
                  ref={el => rightImagesRef.current[index] = el}
                  className="relative group overflow-hidden rounded-2xl"
                  style={{ paddingBottom: `${Math.random() * 40 + 120}%` }}
                >
                  <img
                    src={pin.image_url}
                    alt={pin.title || 'Creative inspiration'}
                    className="absolute inset-0 w-full h-full object-cover transition-all duration-700"
                  />
                  {/* Gradient overlay at bottom */}
                  <div className="absolute inset-0 bg-gradient-to-t from-white via-white/30 to-transparent"></div>
                  
                  {/* Hover effect */}
                  <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Mobile Layout */}
        <div className="lg:hidden mt-12">
          {/* Mobile Hero Text */}
          <div className="text-center mb-10">
            <h1 className="text-4xl font-bold leading-tight mb-6">
              <span className="block text-gray-900">Get your next</span>
              <span className="block text-red-600">chai time snacks idea</span>
            </h1>
            
            {/* Mobile Slider Dots */}
            <div className="flex justify-center space-x-2 mt-6">
              {[...Array(3)].map((_, index) => (
                <div
                  key={index}
                  className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${
                    index === currentImageIndex % 3 
                      ? 'bg-red-600 scale-125' 
                      : 'bg-gray-300'
                  }`}
                ></div>
              ))}
            </div>
          </div>

          {/* Mobile Images Grid */}
          <div className="grid grid-cols-2 gap-4">
            {heroImages.slice(0, 8).map((pin, index) => (
              <div 
                key={pin.id}
                className="relative group overflow-hidden rounded-xl"
                style={{ paddingBottom: '120%' }}
              >
                <img
                  src={pin.image}
                  alt={pin.title || 'Creative inspiration'}
                  className="absolute inset-0 w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-white/80 via-white/20 to-transparent"></div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LandingPage;
